 1	final class DisjointSet {
 2	    private final int[] parent;
 3	    private final int[] rank;
 4	
 5	    DisjointSet(int size) {
 6	        parent = new int[size];
 7	        rank = new int[size];
 8	        for (int i = 0; i < size; i++) {
 9	            parent[i] = i;
10	            rank[i] = 1;
11	        }
12	    }
13	
14	    int find(int node) {
15	        if (parent[node] != node) {
16	            parent[node] = find(parent[node]);
17	        }
18	        return parent[node];
19	    }
20	
21	    boolean union(int first, int second) {
22	        int firstRoot = find(first);
23	        int secondRoot = find(second);
24	
25	        if (firstRoot == secondRoot) {
26	            return false;
27	        }
28	
29	        if (rank[firstRoot] < rank[secondRoot]) {
30	            parent[firstRoot] = secondRoot;
31	        } else if (rank[firstRoot] > rank[secondRoot]) {
32	            parent[secondRoot] = firstRoot;
33	        } else {
34	            parent[secondRoot] = firstRoot;
35	            rank[firstRoot]++;
36	        }
37	
38	        return true;
39	    }
40	}
