 2	    MstResult compute(Graph graph) {
 3	        DisjointSet disjointSet = new DisjointSet(graph.vertexCount());
 4	        int totalWeight = 0;
 5	        int edgesUsed = 0;
 6	
 7	        for (Edge edge : graph.edgesSortedByWeight()) {
 8	            if (!disjointSet.union(edge.from(), edge.to())) {
 9	                continue;
10	            }
11	
12	            totalWeight += edge.weight();
13	            edgesUsed++;
14	
15	            if (edgesUsed == graph.requiredEdgeCount()) {
16	                return new MstResult(totalWeight, edgesUsed);
17	            }
18	        }
19	
20	        MstResult result = new MstResult(totalWeight, edgesUsed);
21	        if (graph.isTriviallyConnected() || result.spans(graph)) {
22	            return result;
23	        }
24	
25	        throw new IllegalArgumentException("Input graph must be connected to form an MST.");
26	    }
